const $=s=>document.querySelector(s);const app=$('#app');let typingTimer=null;
const animals=[['🐶','강아지'],['🐱','고양이'],['🐰','토끼'],['🦁','사자'],['🐯','호랑이'],['🐼','판다'],['🐘','코끼리'],['🦒','기린'],['🐵','원숭이'],['🦊','여우'],['🐻','곰'],['🐧','펭귄'],['🦉','부엉이'],['🐿️','다람쥐'],['🐳','고래'],['🐬','돌고래'],['🐢','거북이'],['🐙','문어'],['🐥','병아리'],['🐸','개구리']];
const seedStudents=[{id:1,school:'별빛초등학교',grade:2,room:'2학년 1반',name:'김민준',code:[0,2,5],active:true},{id:2,school:'별빛초등학교',grade:2,room:'2학년 1반',name:'이서윤',code:[3,8,12],active:true},{id:3,school:'별빛초등학교',grade:3,room:'3학년 2반',name:'박지호',code:[6,1,15],active:true}];
const defaults={students:seedStudents,schools:[],classes:[],records:[],settings:{sound:true,large:false,reduced:false}};
let state=JSON.parse(localStorage.getItem('tadakState')||'null')||structuredClone(defaults);let session={student:null,studentCode:null,adminPassword:null,role:null,login:{school:'',room:'',name:'',code:[]},practice:null,game:null,roomId:null,playerId:null};let composing=false,roomCache={},roomPoll=null,sharedReady=false;
const save=()=>localStorage.setItem('tadakState',JSON.stringify(state));
const roomText=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
async function dataRequest(payload){let response=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json().catch(()=>({error:'공용 데이터 응답을 읽지 못했어요.'}));if(!response.ok)throw new Error(data.error||'공용 데이터에 연결하지 못했어요.');return data}
async function loadSharedData(){let data=await dataRequest({action:'bootstrap'});state.students=data.students.map(s=>({...s,id:Number(s.id)}));state.schools=data.schools||[];state.classes=data.classes||[];boardWords=data.words;sharedReady=true;save();return data}
function animalAvatar(index,size='normal'){let col=index%5,row=Math.floor(index/5);return `<span class="animal-avatar ${size}" style="--animal-x:${col};--animal-y:${row}" aria-hidden="true"></span>`}
function layout(content,opts={}){document.body.className=session.role==='admin'?'admin-mode':'student-mode';app.innerHTML=`<main id="main" class="shell"><header class="topbar"><button class="brand" style="border:0;background:none;color:inherit" onclick="go('${session.role==='admin'?'admin':'home'}')"><span class="brand-mark">⌨️</span><span>타닥타닥 탐험대</span></button><div class="top-actions">${session.student?`<span class="pill">🌟 ${session.student.name} · ${session.student.room}</span>`:''}${session.role?`<button class="btn" onclick="logout()">나가기</button>`:''}</div></header>${content}</main>`}
function go(view,arg){if(view!=='typing'&&typingTimer){clearInterval(typingTimer);typingTimer=null}if(!['roomLobby','roomView','roomGame'].includes(view)&&roomPoll){clearInterval(roomPoll);roomPoll=null}({start,login,home,practice,typing,gameMenu,board,roomLobby,roomView,roomGame,mouse,records,settings,result,admin,organizations,students,words}[view]||start)(arg);scrollTo(0,0)}
function start(){session.role=null;session.student=null;layout(`<section class="hero"><div class="panel"><span class="eyebrow">놀면서 배우는 첫 컴퓨터 여행</span><h1>한 글자씩,<br>신나게 출발!</h1><p>정확하게 누를수록 탐험 지도가 반짝여요. 타자와 마우스를 차근차근 익혀 보세요.</p><div class="row"><button class="btn primary" onclick="go('login')">🚀 학생으로 시작하기</button><button class="btn" onclick="adminLogin()">선생님·관리자</button></div></div><div class="panel mascot"><div><div class="tadaki" aria-label="키보드 배를 가진 하늘색 별 캐릭터"><span>★</span><b>⌨</b></div><h2>타닥이와 같이 탐험할까?</h2><p style="color:#fff">천천히 정확하게 눌러 보자!</p></div></div></section><section class="choice-grid section-title"><div class="card choice typing-card"><div class="icon">⌨️</div><h3>타자연습</h3><p>자리부터 문장까지 차근차근!</p></div><div class="card choice game-card"><div class="icon">🎮</div><h3>타자게임</h3><p>단어를 입력하고 게임에 도전!</p></div><div class="card choice mouse-card"><div class="icon">🖱️</div><h3>마우스놀이</h3><p>움직이고 누르며 마우스와 친해지기!</p></div></section>`)}
function login(){let l=session.login,step=!l.school?1:!l.room?2:!l.name?3:4;let students=state.students.filter(s=>s.active);let body='';if(step===1){body=`<div class="field"><label for="school">학교를 골라 주세요</label><select id="school"><option value="">학교 선택</option>${[...new Set(students.map(s=>s.school))].map(x=>`<option>${x}</option>`)}</select></div><button class="btn primary" onclick="pick('school')">다음</button>`}if(step===2){body=`<button class="btn" onclick="resetLogin(1)">← 학교 다시 고르기</button><div class="field"><label for="room">우리 반을 골라 주세요</label><select id="room"><option value="">반 선택</option>${[...new Set(students.filter(s=>s.school===l.school).map(s=>s.room))].map(x=>`<option>${x}</option>`)}</select></div><button class="btn primary" onclick="pick('room')">다음</button>`}if(step===3){body=`<button class="btn" onclick="resetLogin(2)">← 반 다시 고르기</button><div class="field"><label for="name">내 이름을 골라 주세요</label><select id="name"><option value="">이름 선택</option>${students.filter(s=>s.school===l.school&&s.room===l.room).map(s=>`<option>${s.name}</option>`)}</select></div><button class="btn primary" onclick="pick('name')">다음</button>`}if(step===4){body=`<p><b>${l.name}</b> 탐험가의 동물 3마리를 순서대로 눌러 주세요.</p><div class="selected-code animal-code-preview">${l.code.length?l.code.map(i=>animalAvatar(i,'small')).join(''):'<span class="code-empty">○ ○ ○</span>'}</div><div class="animal-grid">${animals.map((a,i)=>`<button class="animal ${l.code.includes(i)?'selected':''}" aria-label="${a[1]}" onclick="animalPick(${i})">${animalAvatar(i)}<b>${a[1]}</b></button>`).join('')}</div><div class="row" style="margin-top:18px"><button class="btn" onclick="session.login.code=[];login()">모두 지우기</button><button class="btn primary" onclick="studentLogin()" ${l.code.length!==3?'disabled':''}>탐험 시작!</button></div>`}layout(`<section class="panel login-box"><div class="steps">${[1,2,3,4].map(i=>`<i class="step ${i<=step?'on':''}"></i>`).join('')}</div><span class="eyebrow">${step}/4 단계</span><h1>반가워요! 누구인가요?</h1>${body}</section>`)}
function pick(k){let v=$('#'+k).value;if(!v)return;session.login[k]=v;login()}function resetLogin(n){if(n<3)session.login.name='';if(n<2)session.login.room='';if(n<1)session.login.school='';session.login.code=[];login()}function animalPick(i){if(session.login.code.includes(i)||session.login.code.length===3)return;session.login.code.push(i);login()}
function studentLogin(){let l=session.login,s=state.students.find(s=>s.school===l.school&&s.room===l.room&&s.name===l.name&&s.code.join()==l.code.join());if(!s){alert('동물 순서가 맞지 않아요. 천천히 다시 해 볼까요?');l.code=[];return login()}session.student=s;session.role='student';go('home')}
function home(){let r=state.records.filter(x=>x.studentId===session.student.id),best=Math.max(0,...r.map(x=>x.cpm||0)),avg=r.length?Math.round(r.reduce((a,b)=>a+(b.accuracy||0),0)/r.length):0;layout(`<section class="panel welcome"><span class="eyebrow">오늘의 탐험</span><h1>${session.student.name}아, 오늘도 반가워! 👋</h1><p class="muted">오늘은 전체자리 낱말 탐험으로 별 하나를 채워 볼까?</p><div class="stats"><div class="stat"><strong>${best}</strong>최고 타수</div><div class="stat"><strong>${avg}%</strong>평균 정확도</div><div class="stat"><strong>${r.length}회</strong>총 연습</div></div><button class="btn primary" onclick="startTyping('낱말연습','전체자리')">🚀 추천 연습 시작!</button></section><div class="section-title playful-title"><h2>어디로 탐험할까요?</h2><span class="muted">마음 가는 곳을 콕!</span></div><section class="cards home-menu"><button class="card typing-card" onclick="go('practice')"><div class="icon">⌨️</div><span class="scribble">STEP BY STEP</span><h3>타자연습</h3><p>손가락·낱말·긴글을 차근차근!</p></button><button class="card game-card" onclick="go('gameMenu')"><div class="icon">🎮</div><span class="scribble">PLAY!</span><h3>타자게임</h3><p>혼자 또는 친구와 팀을 나눠 도전!</p></button><button class="card mouse-card" onclick="go('mouse')"><div class="icon">🖱️</div><span class="scribble">CLICK!</span><h3>마우스놀이</h3><p>움직이고 누르며 마우스와 친해지기!</p></button></section><div class="section-title playful-title"><h2>나의 탐험 노트</h2></div><section class="cards compact-cards scrapbook"><button class="card" onclick="go('records')"><div class="icon">📈</div><h3>나의 기록</h3><p>조금씩 자라는 나를 확인해요</p></button><button class="card" onclick="go('settings')"><div class="icon">⚙️</div><h3>설정</h3><p>소리와 글자 크기를 바꿔요</p></button></section>`)}
function practice(mode){if(!mode)return layout(`<div class="section-title"><div><span class="eyebrow">타자연습</span><h1>어떤 연습을 시작할까요?</h1><p class="muted">손가락 위치부터 긴 글까지 차근차근 익혀요.</p></div><button class="btn" onclick="go('home')">← 홈</button></div><section class="cards practice-types"><button class="card typing-card" onclick="go('practice','finger')"><div class="icon">🙌</div><span class="card-tag">자리별 선택</span><h3>손가락연습</h3><p>각 키를 담당하는 손가락과 자리를 익혀요.</p></button><button class="card typing-card" onclick="go('practice','word')"><div class="icon">🍎</div><span class="card-tag">자리별 선택</span><h3>낱말연습</h3><p>자리별 핵심 글쇠가 들어간 낱말을 연습해요.</p></button><button class="card typing-card" onclick="startTyping('긴글연습','긴글')"><div class="icon">📖</div><span class="card-tag long">120초</span><h3>긴글연습</h3><p>긴 문장을 이어 입력하며 집중력과 속도를 길러요.</p></button></section>`);let title=mode==='finger'?'손가락연습':'낱말연습',desc=mode==='finger'?'연습할 키보드 자리를 골라 주세요.':'집중해서 연습할 자리를 골라 주세요.';layout(`<div class="section-title"><div><span class="eyebrow">${title}</span><h1>${desc}</h1><p class="muted">왼손과 오른손을 나눠 연습한 뒤 전체자리로 도전해요.</p></div><button class="btn" onclick="go('practice')">← 연습 종류</button></div><section class="lesson-grid">${lessonOrder.map((level,i)=>`<button class="card lesson-card" onclick="startTyping('${title}','${level}')"><span class="lesson-no">${i+1}</span><div class="icon">${lessonIcons[i]}</div><h3>${level}</h3><p>${lessonDescriptions[mode][level]}</p><span class="lesson-go">연습 시작 →</span></button>`).join('')}</section>`)}
